DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM ALL_USERS WHERE USERNAME = 'APP';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE USER "APP" NO AUTHENTICATION DEFAULT TABLESPACE "USERS" QUOTA UNLIMITED ON "USERS"';
  END IF;
END;
